// Parse Zillow page HTML and extract property data
const html = $input.item.json.data;
const cheerio = require('cheerio');
const $ = cheerio.load(html);

// Extract property details
const price = $('[data-test="price"]').first().text().trim();
const address = $('[data-test="property-address"]').text().trim();
const beds = $('[data-test="bed-bath-item"]').first().text().trim();
const baths = $('[data-test="bed-bath-item"]').eq(1).text().trim();
const sqft = $('[data-test="bed-bath-item"]').eq(2).text().trim();
const description = $('[data-test="property-description"]').text().trim().slice(0, 500);

// Extract image URLs (get first 3 high quality images)
const allImages = [];
$('picture img').each((i, elem) => {
  const src = $(elem).attr('src');
  const alt = $(elem).attr('alt') || '';
  if (src && src.includes('https://')) {
    allImages.push({
      url: src.replace(/\/[a-z]_[a-z]\./, '/uncropped_scaled_within_1536_1152.'),
      alt: alt.toLowerCase(),
      index: i
    });
  }
});

// Smart selection: prioritize key rooms
const priorityKeywords = ['kitchen', 'living', 'exterior', 'master', 'bedroom'];
const priorityImages = [];
const regularImages = [];

allImages.forEach(img => {
  if (priorityKeywords.some(keyword => img.alt.includes(keyword))) {
    priorityImages.push(img);
  } else {
    regularImages.push(img);
  }
});

// Take up to 3 images, prioritizing key rooms
const selectedImages = [
  ...priorityImages.slice(0, 3),
  ...regularImages.slice(0, 3 - priorityImages.length)
].slice(0, 3);

return {
  price,
  address,
  beds,
  baths,
  sqft,
  description,
  images: selectedImages.map(img => img.url),
  imageCount: selectedImages.length
};

