// Extract descriptions from Groq response
const response = $input.item.json;
const content = response.choices[0].message.content;

// Split into individual descriptions (assume 3 descriptions separated by newlines)
const descriptions = content.split('\n').filter(line => line.trim().length > 10).slice(0, 3);

// Map each image to its description
const propertyData = items[0].json;
const imageData = propertyData.images.map((imageUrl, index) => ({
  imageUrl,
  description: descriptions[index] || 'Beautiful property feature',
  index
}));

return imageData.map(item => ({
  ...propertyData,
  currentImage: item.imageUrl,
  currentDescription: item.description,
  imageIndex: item.index
}));

// Store taskId with image info
return {
  taskId: $input.item.json.data.taskId,
  imageUrl: items[0].json.currentImage,
  description: items[0].json.currentDescription,
  imageIndex: items[0].json.imageIndex,
  propertyData: {
    address: items[0].json.address,
    price: items[0].json.price,
    beds: items[0].json.beds,
    baths: items[0].json.baths,
    sqft: items[0].json.sqft
  }
};

// Extract video URL from kie.ai response
const resultJson = JSON.parse($input.item.json.data.resultJson);
const videoUrl = resultJson.resultUrls[0];

return {
  videoUrl: videoUrl,
  imageUrl: items[0].json.imageUrl,
  description: items[0].json.description,
  imageIndex: items[0].json.imageIndex,
  propertyData: items[0].json.propertyData
};

// Organize all video clips
const videos = items.map(item => ({
  videoUrl: item.json.videoUrl,
  description: item.json.description,
  imageIndex: item.json.imageIndex
})).sort((a, b) => a.imageIndex - b.imageIndex);

const propertyData = items[0].json.propertyData;

return {
  success: true,
  property: propertyData,
  videos: videos,
  videoCount: videos.length,
  cost: {
    total: videos.length * 0.15,
    perVideo: 0.15,
    breakdown: {
      animation: videos.length * 0.15,
      script: 0.00,
      total: videos.length * 0.15
    }
  },
  processingTime: new Date().toISOString()
};
